let S;try{S=JSON.parse(localStorage.getItem(K))||seed()}catch{S=seed()}S.profile={...seed().profile,...S.profile};S.settings={...seed().settings,...S.settings};S.activities=Array.isArray(S.activities)?S.activities:[];S.tasks=Array.isArray(S.tasks)?S.tasks:[];S.routines=Array.isArray(S.routines)?S.routines:[];S.routineSkips=Array.isArray(S.routineSkips)?S.routineSkips:[];S.attendance=Array.isArray(S.attendance)?S.attendance:[];S.goals=Array.isArray(S.goals)?S.goals:[];S.projects=Array.isArray(S.projects)?S.projects:[];S.finance=Array.isArray(S.finance)?S.finance:[];S.notes=Array.isArray(S.notes)?S.notes:[];S.journal=S.journal||{};S.meta={version:3,...(S.meta||{})};
