function activityXP(a){const d=clamp(+a.duration||0,1,480),w=XP_WEIGHT[a.category]||1;let bonus=a.source==='pomodoro'&&a.completed!==false?12:0;if(a.source==='routine')bonus+=4;if(a.obligation==='mandatory')bonus+=5;if(a.goalId)bonus+=8;return Math.max(1,Math.round(d*w+bonus))}
