const GOOGLE_SCOPES=['openid','email','profile','https://www.googleapis.com/auth/calendar.readonly','https://www.googleapis.com/auth/gmail.metadata','https://www.googleapis.com/auth/drive.metadata.readonly'].join(' ');
let G={token:null,expiresAt:0,profile:null,calendar:[],gmail:[],drive:[],lastSync:null,loading:false,error:null};
