function loadGoogleGIS(){return new Promise((resolve,reject)=>{if(window.google?.accounts?.oauth2)return resolve();let old=document.querySelector('script[data-google-gis]');if(old){old.addEventListener('load',()=>resolve(),{once:true});old.addEventListener('error',()=>reject(new Error('Google Identity Services gagal dimuat')),{once:true});return}let s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.defer=true;s.dataset.googleGis='1';s.onload=()=>resolve();s.onerror=()=>reject(new Error('Google Identity Services gagal dimuat'));document.head.appendChild(s)})}
