async function syncGoogle(){if(!googleReady()){toast('Hubungkan Google terlebih dahulu');return}G.loading=true;G.error=null;render();try{const now=new Date().toISOString(),calUrl='https://www.googleapis.com/calendar/v3/calendars/primary/events?singleEvents=true&orderBy=startTime&maxResults=12&timeMin='+encodeURIComponent(now),gmList='https://gmail.googleapis.com/gmail/v1/users/me/messages?maxResults=8&q='+encodeURIComponent('newer_than:14d'),driveUrl='https://www.googleapis.com/drive/v3/files?pageSize=8&orderBy=modifiedTime%20desc&fields='+encodeURIComponent('files(id,name,mimeType,modifiedTime,webViewLink)');const [profile,cal,msgs,drive]=await Promise.all([googleFetch('https://www.googleapis.com/oauth2/v3/userinfo'),googleFetch(calUrl),googleFetch(gmList),googleFetch(driveUrl)]);G.profile=profile;G.calendar=cal.items||[];G.drive=drive.files||[];const ids=(msgs.messages||[]).slice(0,8);G.gmail=await Promise.all(ids.map(m=>googleFetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/'+m.id+'?format=metadata&metadataHeaders=Subject&metadataHeaders=From&metadataHeaders=Date')));G.lastSync=Date.now()}catch(e){G.error=e.message;toast('Google sync gagal: '+e.message)}finally{G.loading=false;render()}}
