function focusPhaseLabel(){return focus.phase==='focus'?'FOKUS':focus.phase==='longBreak'?'ISTIRAHAT PANJANG':'ISTIRAHAT'}
function focusTimeText(){return String(Math.floor(focus.left/60)).padStart(2,'0')+':'+String(focus.left%60).padStart(2,'0')}
function ensureFocusOverlay(){let z=$('#focusZen');if(z)return z;z=document.createElement('section');z.id='focusZen';z.className='focus-zen';z.hidden=true;z.setAttribute('aria-live','polite');z.innerHTML='<div class="zen-top"><div class="zen-brand"><span class="brand-mark">D</span><div><b>Desca OS</b><small>Focus Mode</small></div></div><button class="zen-minimize" data-act="minimizeFocus" type="button">Minimize</button></div><div class="zen-center"><div class="zen-phase" id="zenPhase">FOKUS</div><div class="zen-session" id="zenSession">Belajar Fokus</div><div class="zen-clock-wrap"><div class="zen-ring" id="zenRing"><div class="zen-clock" id="zenClock">25:00</div></div></div><div class="zen-meta"><span id="zenCategory">Study</span><span>•</span><span id="zenCycle">Sesi 1 / 4</span></div><div class="zen-actions"><button class="zen-main" data-act="focus" type="button" id="zenPlay">Pause</button><button class="zen-secondary" data-act="resetFocus" type="button">Akhiri sesi</button><button class="zen-secondary" data-act="skipBreak" type="button" id="zenSkip">Lewati istirahat</button></div><div class="zen-tip">Space untuk pause/resume • Esc untuk minimize</div></div>';document.body.append(z);let d=document.createElement('button');d.id='focusDock';d.className='focus-dock';d.hidden=true;d.type='button';d.dataset.act='restoreFocus';d.innerHTML='<span class="focus-dock-dot"></span><span><b id="dockClock">25:00</b><small id="dockLabel">Focus Mode</small></span><span>↗</span>';document.body.append(d);return z}
function tryNativeFullscreen(){const el=document.documentElement;if(!document.fullscreenElement&&el.requestFullscreen)el.requestFullscreen().catch(()=>{})}
function exitNativeFullscreen(){if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{})}
function updateFocusOverlay(){const z=ensureFocusOverlay(),dock=$('#focusDock'),cycles=clamp(+S.settings.pomodoroCycles||4,1,12),pct=clamp((1-focus.left/Math.max(1,focus.total))*100,0,100),active=!!(focus.startedAt||focus.running||focus.phase!=='focus');z.hidden=!focus.zen;dock.hidden=focus.zen||!active;document.body.classList.toggle('focus-zen-active',focus.zen);$('#zenPhase').textContent=focusPhaseLabel();$('#zenSession').textContent=focus.phase==='focus'?(focus.label||'Belajar Fokus'):'Pulihkan energi';$('#zenClock').textContent=focusTimeText();$('#zenCategory').textContent=cat(focus.category);$('#zenCycle').textContent='Sesi '+focus.cycle+' / '+cycles;$('#zenRing').style.setProperty('--zen-progress',pct+'%');$('#zenPlay').textContent=focus.running?'Pause':focus.phase==='focus'?'Lanjut Fokus':'Mulai Istirahat';$('#zenSkip').hidden=focus.phase==='focus';$('#dockClock').textContent=focusTimeText();$('#dockLabel').textContent=focusPhaseLabel()+' • '+(focus.phase==='focus'?(focus.label||cat(focus.category)):'Break')}
function enterFocusMode(native=true){focus.zen=true;updateFocusOverlay();if(native)tryNativeFullscreen()}
function minimizeFocus(){focus.zen=false;updateFocusOverlay();exitNativeFullscreen()}
function phaseMinutes(){return focus.phase==='focus'?focus.work:focus.phase==='longBreak'?focus.long:focus.short}
function syncPomodoro(){focus.work=clamp(+S.settings.pomodoroFocus||25,5,180);focus.short=clamp(+S.settings.pomodoroShortBreak||5,1,60);focus.long=clamp(+S.settings.pomodoroLongBreak||15,1,90);if(!focus.running){focus.total=phaseMinutes()*60;focus.left=focus.total}}

function stats(d=today()){const A=S.activities.filter(x=>x.date===d),T=S.tasks.filter(x=>x.date===d),D=T.filter(x=>x.status==='done'),productive=A.reduce((a,x)=>a+(+x.duration||0),0),completion=T.length?Math.round(D.length/T.length*100):0,score=Math.round(((T.length?D.length/T.length:0)*.45+clamp(productive/S.profile.dailyFocusTarget,0,1)*.45+(attendanceRecord(d)?0.10:0))*100);return{A,T,D,productive,completion,score,xp:A.reduce((a,x)=>a+activityXP(x),0)+D.reduce((a,x)=>a+taskXP(x),0)+attendanceXPForDate(d)}}
function streak(){let n=0;for(let i=0;i<365;i++){let s=stats(add(today(),-i));if(s.productive||s.D.length)n++;else break}return n}
function attendanceStreak(){let n=0;for(let i=0;i<365;i++){if(attendanceRecord(add(today(),-i)))n++;else break}return n}
function checkIn(){let old=attendanceRecord();if(old){toast('Presensi hari ini sudah tercatat pukul '+old.time);return}const r={id:uid('att'),date:today(),time:localTime(),timestamp:Date.now()};S.attendance.push(r);save();toast('Presensi tercatat · +15 XP');render()}
function learningActivities(){return S.activities.filter(x=>['study','research','english'].includes(x.category)&&/^\d{2}:\d{2}$/.test(x.startTime||'')&&x.date>=add(today(),-89))}
function studyInsights(){const a=learningActivities(),slots=new Map(),days=new Map();for(const x of a){const h=clamp(parseInt(x.startTime.slice(0,2),10)||0,0,23),start=Math.floor(h/2)*2,key=start;let s=slots.get(key)||{start,sessions:0,minutes:0,completed:0};s.sessions++;s.minutes+=+x.duration||0;s.completed+=x.completed===false?0:1;slots.set(key,s);const wd=new Date(x.date+'T12:00:00').getDay();let d=days.get(wd)||{sessions:0,minutes:0};d.sessions++;d.minutes+=+x.duration||0;days.set(wd,d)}
const ranked=[...slots.values()].map(s=>{s.avg=s.sessions?s.minutes/s.sessions:0;s.completion=s.sessions?s.completed/s.sessions:0;s.score=s.avg*.6+s.completion*25+Math.min(s.sessions,8)/8*20;s.label=String(s.start).padStart(2,'0')+':00–'+String((s.start+2)%24).padStart(2,'0')+':00';return s}).sort((a,b)=>b.score-a.score),best=ranked[0]||null,dayRank=[...days.entries()].map(([day,d])=>({day,...d,avg:d.minutes/d.sessions})).sort((a,b)=>b.avg-a.avg),names=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'],count=a.length,avg=count?a.reduce((z,x)=>z+(+x.duration||0),0)/count:0,confidence=count>=12?'Tinggi':count>=6?'Sedang':'Awal';return{enough:count>=3,count,avg,best,slots:ranked,strongDay:dayRank[0]?names[dayRank[0].day]:'—',confidence}}
function recommendationCard(){const i=studyInsights();if(!i.enough)return'<article class="card recommendation-card"><div class="card-head"><div><h2>Rekomendasi Waktu Belajar</h2><p>Dihitung otomatis dari histori 90 hari.</p></div><span class="pill orange">Belum cukup data</span></div><div class="empty">Butuh minimal 3 sesi belajar yang memiliki jam mulai. Pomodoro akan mencatat jam ini otomatis; activity manual juga sekarang memiliki field jam mulai.</div></article>';return'<article class="card recommendation-card"><div class="card-head"><div><h2>Rekomendasi Waktu Belajar</h2><p>Berdasarkan '+i.count+' sesi belajar/riset/English dalam 90 hari.</p></div><span class="pill green">Confidence '+i.confidence+'</span></div><div class="recommend-time">'+i.best.label+'</div><div class="recommend-copy">Di rentang ini rata-rata sesi efektifmu '+mins(i.best.avg)+' dengan '+i.best.sessions+' sesi tercatat. Hari yang paling kuat: <b>'+i.strongDay+'</b>.</div><div class="callout" style="margin-top:12px">Rekomendasi ini mengikuti pola produktivitas historismu, bukan penilaian kemampuan kognitif. Nilainya akan berubah otomatis saat histori bertambah.</div></article>'}
function attendanceCard(){const a=attendanceRecord();return'<article class="card attendance-card '+(a?'checked':'')+'"><div class="card-head"><div><h2>Presensi Harian</h2><p>Satu klik untuk menandai kamu hadir dan mulai hari.</p></div><span class="pill '+(a?'green':'')+'">'+(a?'HADIR':'BELUM')+'</span></div><div class="attendance-row"><div><div class="attendance-streak">'+attendanceStreak()+' hari</div><div class="item-meta">streak presensi'+(a?' • hari ini '+a.time:'')+'</div></div><button class="btn '+(a?'btn-secondary':'btn-primary')+'" data-act="checkIn" '+(a?'disabled':'')+'>'+(a?'✓ Sudah Presensi':'Presensi Sekarang')+'</button></div></article>'}
const catMin=(c,days=7)=>S.activities.filter(x=>x.category===c&&x.date>=add(today(),-(days-1))).reduce((a,x)=>a+(+x.duration||0),0);syncPomodoro();
function weeks(off=0){let d=new Date(today()+'T12:00:00'),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day+off*7);return Array.from({length:7},(_,i)=>{let x=new Date(d);x.setDate(d.getDate()+i);return iso(x)})}const weekMin=off=>weeks(off).reduce((a,d)=>a+stats(d).productive,0);
function toast(t){let e=document.createElement('div');e.className='toast';e.textContent=t;$('#toastWrap').append(e);setTimeout(()=>e.remove(),2400)}
function side(){const l=level();$('#sideLevel').textContent=l.level;$('#sideXP').textContent=num(xp())+' XP';$('#sideXPBar').style.width=l.pct+'%'}
function nav(){for(const g of ['CORE','GROWTH','LIFE','INSIGHTS','SYSTEM']){ }$('#sideNav').innerHTML=['CORE','GROWTH','LIFE','INSIGHTS','SYSTEM'].map(g=>'<div class="nav-group"><div class="nav-label">'+g+'</div>'+Object.entries(R).filter(([,v])=>v[2]===g).map(([k,v])=>'<button class="nav-item '+(route===k?'active':'')+'" data-route="'+k+'"><span class="nav-icon">'+v[1]+'</span><span>'+v[0]+'</span></button>').join('')+'</div>').join('');$('#bottomNav').innerHTML=[['today','◉','Today'],['life','◫','Life Log'],['tasks','✓','Tasks'],['progress','▤','Progress'],['analytics','•••','More']].map(x=>'<button class="bottom-item '+(route===x[0]?'active':'')+'" data-route="'+x[0]+'"><span>'+x[1]+'</span><span>'+x[2]+'</span></button>').join('');$('#crumb').textContent=R[route][0]}
const head=(t,d,a='')=>'<div class="page-head"><div><div class="eyebrow">Desca OS</div><h1>'+esc(t)+'</h1><p>'+esc(d)+'</p></div><div class="page-actions">'+a+'</div></div>',prog=p=>'<div class="progress-track"><span style="width:'+clamp(+p||0,0,100)+'%"></span></div>',metric=(l,v,m,i)=>'<div class="metric-card"><div class="metric-icon">'+i+'</div><div class="metric-label">'+l+'</div><div class="metric-value">'+v+'</div><div class="metric-meta">'+m+'</div></div>';
function task(x){return'<div class="task-item"><button class="check '+(x.status==='done'?'done':'')+'" data-act="toggle" data-id="'+x.id+'">'+(x.status==='done'?'✓':'')+'</button><div class="item-main"><div class="item-title '+(x.status==='done'?'done':'')+'">'+esc(x.title)+'</div><div class="item-meta"><span>'+cat(x.category)+'</span><span>• '+mins(x.estimate)+'</span>'+(x.goalId?'<span>• '+esc(goal(x.goalId))+'</span>':'')+'<span class="pill '+(x.priority==='high'?'red':x.priority==='medium'?'orange':'')+'">'+x.priority+'</span><span class="xp-pop">+'+taskXP(x)+' XP</span></div></div><button class="mini-btn" data-act="editTask" data-id="'+x.id+'">Edit</button></div>'}
function goalCard(g){return'<div class="goal-card"><div class="goal-top"><div><div class="goal-title">'+esc(g.title)+'</div><div class="goal-sub">'+esc(g.area)+' • '+fmt(g.deadline,{day:'numeric',month:'short',year:'numeric'})+'</div></div><span class="pill blue">'+g.status+'</span></div><div class="goal-progress">'+prog(g.progress)+'<b>'+g.progress+'%</b></div></div>'}
function focusCard(){let mm=String(Math.floor(focus.left/60)).padStart(2,'0'),ss=String(focus.left%60).padStart(2,'0'),cycles=clamp(+S.settings.pomodoroCycles||4,1,12),phase=focus.phase==='focus'?'FOCUS':focus.phase==='longBreak'?'LONG BREAK':'SHORT BREAK';return'<article class="card focus-card pomodoro-card"><div class="card-head"><div><h2>Pomodoro Focus</h2><p>'+phase+' • sesi '+focus.cycle+' / '+cycles+'</p></div><span class="pill">'+(focus.running?'RUNNING':phase)+'</span></div><div class="pomodoro-presets"><button class="pomo-preset '+(S.settings.pomodoroPreset==='classic'?'active':'')+'" data-act="pomoPreset" data-preset="classic" '+(focus.running?'disabled':'')+'>25 / 5</button><button class="pomo-preset '+(S.settings.pomodoroPreset==='deep'?'active':'')+'" data-act="pomoPreset" data-preset="deep" '+(focus.running?'disabled':'')+'>50 / 10</button><button class="pomo-preset '+(S.settings.pomodoroPreset==='custom'?'active':'')+'" data-act="pomoPreset" data-preset="custom" '+(focus.running?'disabled':'')+'>Custom</button></div><div class="focus-clock" id="focusClock">'+mm+':'+ss+'</div><div class="focus-mode">'+(focus.phase==='focus'?phaseMinutes()+' menit fokus':phaseMinutes()+' menit pemulihan')+'</div>'+(focus.phase==='focus'?'<div class="pomodoro-context"><input id="focusLabel" aria-label="Nama sesi fokus" value="'+esc(focus.label)+'" '+(focus.running?'disabled':'')+'><select id="focusCategory" aria-label="Kategori sesi" '+(focus.running?'disabled':'')+'>'+Object.keys(C).map(x=>'<option value="'+x+'" '+(focus.category===x?'selected':'')+'>'+cat(x)+'</option>').join('')+'</select></div>':'<div class="break-note">Istirahat tidak menambah productive time atau XP. Setelah break selesai, sesi fokus berikutnya siap otomatis.</div>')+'<div class="focus-actions"><button class="btn btn-primary" data-act="focus">'+(focus.running?'Pause':focus.phase==='focus'?'Start Focus':'Start Break')+'</button><button class="btn btn-secondary" data-act="resetFocus">Reset</button>'+(focus.phase!=='focus'?'<button class="btn btn-secondary" data-act="skipBreak">Skip Break</button>':'')+'</div></article>'}
function timeline(d){let a=S.activities.filter(x=>x.date===d).slice(-8).reverse();return a.length?a.map(x=>'<div class="timeline-item"><span>•</span><div class="item-main"><div class="item-title">'+esc(x.title)+'</div><div class="item-meta"><span>'+cat(x.category)+'</span><span>• '+mins(x.duration)+'</span>'+(x.startTime?'<span>• '+x.startTime+'</span>':'')+'<span class="xp-pop">+'+activityXP(x)+' XP</span></div></div></div>').join(''):'<div class="empty">Belum ada aktivitas tercatat.</div>'}
function todayPage(){let t=today(),s=stats(),hr=+new Intl.DateTimeFormat('en-US',{timeZone:S.profile.timezone,hour:'2-digit',hour12:false}).format(new Date()),greet=hr<11?'Selamat pagi':hr<15?'Selamat siang':hr<18?'Selamat sore':'Selamat malam',wk=weekMin(0),pri=S.tasks.filter(x=>x.date===t&&x.status!=='done').slice(0,3);
$('#page').innerHTML=starterCard()+'<section class="hero-greeting dashboard-hero"><div><div class="eyebrow">'+fmt(t)+'</div><h1>'+greet+', '+esc(S.profile.name)+'.</h1><p>Fokus pada hal penting hari ini. Sistem akan menghitung progres, XP, dan pola belajarmu otomatis.</p></div><div class="daily-score"><div class="score-ring" style="--score:'+s.score+'%"><b>'+s.score+'</b></div><div class="score-copy"><b>Daily Score</b><span>'+ (s.score>=70?'Progress yang kuat':'Masih banyak ruang hari ini')+'</span></div></div></section><section class="grid metric-grid">'+metric('Daily Progress',s.completion+'%',s.D.length+'/'+s.T.length+' task selesai','✓')+metric('Focus Time',mins(s.productive),'Target '+mins(S.profile.dailyFocusTarget),'◷')+metric('XP Today','+'+num(s.xp),'100% otomatis','✦')+metric('Productive Streak',streak()+' hari','Berdasarkan aktivitas','🔥')+metric('This Week',mins(wk),Math.round(wk/S.profile.weeklyTarget*100)+'% dari target','▤')+'</section><section class="grid two-col"><div class="grid"><article class="card"><div class="card-head"><div><h2>Top Priorities</h2><p>Maksimum tiga hal penting hari ini.</p></div><button class="btn btn-secondary" data-act="addTask">+ Task</button></div><div class="priority-list">'+(pri.length?pri.map(task).join(''):'<div class="empty">Belum ada prioritas aktif hari ini.</div>')+'</div></article><article class="card"><div class="card-head"><div><h2>Today Tasks</h2><p>'+s.D.length+' selesai dari '+s.T.length+' task.</p></div><button class="btn btn-ghost" data-route="tasks">Lihat semua →</button></div><div class="task-list">'+(s.T.length?s.T.map(task).join(''):'<div class="empty">Belum ada task untuk hari ini.</div>')+'</div></article>'+todayLifeCard()+'<article class="card"><div class="card-head"><div><h2>Activity Timeline</h2><p>Aktivitas hari ini.</p></div><button class="btn btn-secondary" data-act="addActivity">+ Activity</button></div>'+timeline(t)+'</article></div><div class="grid">'+attendanceCard()+focusCard()+recommendationCard()+'<article class="card"><div class="card-head"><div><h2>Weekly Target</h2><p>'+mins(wk)+' / '+mins(S.profile.weeklyTarget)+'</p></div><span class="pill blue">'+Math.round(wk/S.profile.weeklyTarget*100)+'%</span></div>'+prog(wk/S.profile.weeklyTarget*100)+'<div class="simple-list" style="margin-top:14px">'+Object.keys(C).slice(0,5).map(c=>'<div class="goal-card"><div class="goal-top"><span>'+C[c][1]+' '+C[c][0]+'</span><b>'+mins(catMin(c,7))+'</b></div>'+prog(catMin(c,7)/360*100)+'</div>').join('')+'</div></article><article class="card"><div class="card-head"><div><h2>Current Goals</h2><p>Hubungkan hari ini dengan tujuan besar.</p></div><button class="btn btn-ghost" data-route="goals">Semua →</button></div><div class="goal-list">'+(S.goals.length?S.goals.map(goalCard).join(''):'<div class="empty">Belum ada goal aktif.</div>')+'</div></article><article class="note-card"><div class="card-head"><div><h2>Quick Note</h2><p>Tangkap ide tanpa mengganggu fokus.</p></div></div><textarea id="quickNote" placeholder="Tulis sesuatu..."></textarea><button class="btn btn-primary" data-act="saveNote">Simpan catatan</button></article></div></section>'}
