function financePage(){let inc=S.finance.filter(x=>x.type==='income').reduce((a,x)=>a+(+x.amount||0),0),out=S.finance.filter(x=>x.type==='expense').reduce((a,x)=>a+(+x.amount||0),0),bal=inc-out;$('#page').innerHTML=head('Finance','Catat arus uang secara ringan tanpa mengubah Desca OS menjadi aplikasi akuntansi.','<button class="btn btn-primary" data-act="newFinance">+ Transaksi</button>')+'<section class="grid metric-grid compact-metrics">'+metric('Balance',money(bal),'Tracked balance','¤')+metric('Income',money(inc),'Pemasukan','↑')+metric('Expenses',money(out),'Pengeluaran','↓')+metric('Savings Rate',(inc?Math.round(bal/inc*100):0)+'%','Dari data tercatat','%')+metric('Transactions',S.finance.length,'Entri','▤')+'</section><article class="card"><div class="card-head"><div><h2>Transaction History</h2><p>Terbaru di atas.</p></div></div><div class="simple-list">'+(S.finance.length?S.finance.slice().reverse().map(x=>'<div class="list-row finance-row"><span class="finance-icon '+(x.type==='income'?'income':'expense')+'">'+(x.type==='income'?'↑':'↓')+'</span><div class="item-main"><div class="item-title">'+esc(x.title)+'</div><div class="item-meta">'+fmt(x.date,{day:'numeric',month:'short',year:'numeric'})+' • '+esc(x.category||'General')+'</div></div><b class="finance-value '+(x.type==='income'?'income':'expense')+'">'+(x.type==='income'?'+':'-')+money(x.amount)+'</b></div>').join(''):'<div class="empty empty-state-large"><span class="empty-icon">¤</span><b>Belum ada transaksi.</b><small>Tambahkan pemasukan atau pengeluaran pertama.</small><button class="btn btn-primary" data-act="newFinance">Tambah Transaksi</button></div>')+'</div></article>'}
