function analyticsPage(){let w=weekMin(0),p=weekMin(-1),delta=p?Math.round((w-p)/p*100):(w?100:0),cs=Object.keys(C).map(c=>[c,catMin(c,30)]).sort((a,b)=>b[1]-a[1]),i=studyInsights(),weekAttendance=weeks().filter(d=>attendanceRecord(d)).length,pomos=S.activities.filter(x=>x.source==='pomodoro'&&x.completed!==false&&x.date>=add(today(),-29)).length,adh=routineAdherence(30),a30=S.activities.filter(a=>a.date>=add(today(),-29)),unplanned=a30.filter(a=>a.planned===false),unplannedMin=unplanned.reduce((n,a)=>n+(+a.duration||0),0);$('#page').innerHTML=head('Analytics','Temukan pola dari data aktivitasmu. Semua insight dihitung otomatis.')+'<section class="grid metric-grid">'+metric('This Week',mins(w),(delta>=0?'▲ ':'▼ ')+Math.abs(delta)+'% vs lalu','▤')+metric('Routine Adherence',adh.pct+'%',adh.done+'/'+adh.due+' occurrence 30D','✓')+metric('Unplanned Time',mins(unplannedMin),unplanned.length+' kegiatan 30D','↯')+metric('Best Study Window',i.enough?i.best.label:'Belum cukup data',i.enough?'Confidence '+i.confidence:i.count+'/3 sesi minimum','★')+metric('Attendance',weekAttendance+'/7','Minggu ini','✓')+'</section><div class="grid two-col"><article class="card"><div class="card-head"><h2>Weekly Productive Time</h2></div>'+bars()+'</article><article class="card"><div class="card-head"><h2>30-Day Distribution</h2></div><div class="simple-list">'+cs.slice(0,6).map(([c,m])=>'<div class="goal-card"><div class="goal-top"><span>'+cat(c)+'</span><b>'+mins(m)+'</b></div>'+prog(m/Math.max(...cs.map(x=>x[1]),1)*100)+'</div>').join('')+'</div></article></div><div class="grid two-col section-gap"><article class="card"><div class="card-head"><div><h2>Life Log Quality</h2><p>Plan vs actual selama 30 hari.</p></div></div><div class="simple-list"><div class="list-row"><div class="item-main"><div class="item-title">Routine adherence</div><div class="item-meta">'+adh.pct+'% semua routine • '+adh.mandatoryPct+'% kegiatan wajib</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Spontaneous activity</div><div class="item-meta">'+unplanned.length+' kegiatan • '+mins(unplannedMin)+'</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Total activities</div><div class="item-meta">'+a30.length+' log dalam 30 hari</div></div></div></div></article>'+recommendationCard()+'</div>'}
function reviewPage(){let w=weekMin(0),p=weekMin(-1),att=weeks().filter(d=>attendanceRecord(d)).length,pomo=weeks().reduce((n,d)=>n+S.activities.filter(x=>x.date===d&&x.source==='pomodoro'&&x.completed!==false).length,0),i=studyInsights();$('#page').innerHTML=head('Reviews','Tinjau plan vs actual dan tentukan fokus berikutnya.')+'<article class="card review-hero"><div class="grid two-col"><div><div class="eyebrow" style="color:#7EDBFF">Weekly Review</div><div class="review-number">'+mins(w)+'</div><div class="muted">'+(p?Math.abs(Math.round((w-p)/p*100))+'% vs minggu lalu':'Baseline pertama')+'</div></div><div class="stat-strip"><div class="stat-chip"><b>'+weeks().reduce((a,d)=>a+stats(d).D.length,0)+'</b><span>tasks completed</span></div><div class="stat-chip"><b>+'+weeks().reduce((a,d)=>a+stats(d).xp,0)+'</b><span>XP earned</span></div><div class="stat-chip"><b>'+pomo+'</b><span>Pomodoro selesai</span></div><div class="stat-chip"><b>'+att+'/7</b><span>presensi</span></div></div></div></article><div class="grid two-col" style="margin-top:16px">'+recommendationCard()+'<article class="card"><div class="card-head"><h2>Learning Signal</h2></div><div class="callout">'+(i.enough?'Pola terkuat saat ini: '+i.best.label+' pada '+i.strongDay+'. Prioritaskan blok waktu itu untuk materi yang paling menuntut konsentrasi.':'Belum ada cukup histori bertimestamp. Jalankan sedikitnya 3 sesi Pomodoro agar rekomendasi mulai terbentuk.')+'</div></article></div><article class="card" style="margin-top:16px"><div class="card-head"><h2>Goal Check</h2></div><div class="goal-list">'+(S.goals.length?S.goals.map(goalCard).join(''):'<div class="empty">Belum ada goal.</div>')+'</div></article>'}
function achievementsPage(){let A=[['🌱','The Beginning','Catat aktivitas pertama',S.activities.length>0],['🔥','Consistent','Streak produktif 7 hari',streak()>=7],['⚡','Unstoppable','Streak produktif 30 hari',streak()>=30],['📚','Scholar','50 sesi belajar',S.activities.filter(x=>x.category==='study').length>=50],['⏱','Pomodoro Habit','25 Pomodoro selesai',S.activities.filter(x=>x.source==='pomodoro'&&x.completed!==false).length>=25],['✓','Show Up','Presensi 14 hari',S.attendance.length>=14],['🧠','Deep Thinker','10.000 XP otomatis',xp()>=10000],['📑','Researcher','30 sesi riset',S.activities.filter(x=>x.category==='research').length>=30],['🏃','Runner','20 sesi olahraga',S.activities.filter(x=>x.category==='health').length>=20],['✦','Level Up','Level 10',level().level>=10]];$('#page').innerHTML=head('Achievements','Rayakan konsistensi yang tercatat otomatis.')+'<div class="grid achievement-grid">'+A.map(x=>'<div class="achievement '+(x[3]?'':'locked')+'"><div class="achievement-icon">'+x[0]+'</div><h3>'+x[1]+'</h3><p>'+x[2]+'</p><span class="pill '+(x[3]?'green':'')+'">'+(x[3]?'Unlocked':'Locked')+'</span></div>').join('')+'</div>'}
function calendarPage(){let t=today();$('#page').innerHTML=head('Calendar','Ringkasan task dan rutinitas tujuh hari ke depan.','<button class="btn btn-primary" data-act="addTask">+ Jadwalkan</button>')+'<div class="grid">'+Array.from({length:7},(_,i)=>{let d=add(t,i),ts=S.tasks.filter(x=>x.date===d),rs=dueRoutines(d);return'<article class="card calendar-day"><div class="card-head"><div><h2>'+fmt(d,{weekday:'long',day:'numeric',month:'short'})+'</h2><p>'+ts.length+' task • '+rs.length+' routine</p></div></div>'+(rs.length?'<div class="calendar-routines">'+rs.map(r=>'<div class="calendar-routine"><span>'+esc(r.time||'—')+'</span><b>'+esc(r.title)+'</b><span class="pill '+(r.obligation==='mandatory'?'red':r.obligation==='important'?'orange':'')+'">'+(OBLIGATION_LABEL[r.obligation]||'Penting')+'</span></div>').join('')+'</div>':'')+'<div class="task-list">'+(ts.length?ts.map(task).join(''):'<div class="empty empty-compact">Tidak ada task.</div>')+'</div></article>'}).join('')+'</div>'}
function settingsPage(){$('#page').innerHTML=head('Settings','Atur target dan mesin Pomodoro. XP serta analytics dihitung otomatis dari aktivitas.')+'<div class="grid two-col"><article class="card"><div class="card-head"><h2>Profile & Targets</h2></div><div class="form-grid"><div class="field"><label>Nama</label><input id="sn" value="'+esc(S.profile.name)+'"></div><div class="field"><label>Daily target (menit)</label><input id="sd" type="number" min="1" value="'+S.profile.dailyFocusTarget+'"></div><div class="field"><label>Weekly target (menit)</label><input id="sw" type="number" min="1" value="'+S.profile.weeklyTarget+'"></div></div><button class="btn btn-primary" style="margin-top:12px" data-act="saveSettings">Simpan</button></article><article class="card"><div class="card-head"><div><h2>Pomodoro Engine</h2><p>Preset dapat dipilih langsung dari Today.</p></div><span class="pill blue">'+S.settings.pomodoroPreset+'</span></div><div class="form-grid"><div class="field"><label>Focus (menit)</label><input id="spf" type="number" min="5" max="180" value="'+S.settings.pomodoroFocus+'"></div><div class="field"><label>Short break</label><input id="sps" type="number" min="1" max="60" value="'+S.settings.pomodoroShortBreak+'"></div><div class="field"><label>Long break</label><input id="spl" type="number" min="1" max="90" value="'+S.settings.pomodoroLongBreak+'"></div><div class="field"><label>Sesi sebelum long break</label><input id="spc" type="number" min="1" max="12" value="'+S.settings.pomodoroCycles+'"></div></div><div class="callout" style="margin-top:12px">Mengubah angka di sini menjadikan preset <b>Custom</b>. Sesi fokus yang selesai otomatis masuk Activity Log beserta jam mulai dan XP.</div></article><article class="card"><div class="card-head"><h2>Automatic XP</h2></div><div class="simple-list"><div class="list-row"><div class="item-main"><div class="item-title">Activity XP</div><div class="item-meta">Durasi × bobot kategori + bonus Pomodoro + bonus linked goal.</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Task XP</div><div class="item-meta">Estimasi durasi × prioritas. Hanya dihitung ketika task selesai.</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Attendance XP</div><div class="item-meta">+15 XP per presensi harian.</div></div></div></div></article><article class="card"><div class="card-head"><div><h2>Google Integration</h2><p>Client ID boleh disimpan lokal; client secret tidak pernah dibutuhkan di browser.</p></div><span class="pill '+(googleConfigured()?'green':'orange')+'">'+(googleConfigured()?'CONFIGURED':'SETUP')+'</span></div><div class="field"><label>Google OAuth Client ID</label><input id="sgcid" value="'+esc(S.settings.googleClientId||'')+'" placeholder="xxxxxxxx.apps.googleusercontent.com"></div><div class="callout" style="margin-top:12px">Authorized JavaScript origin untuk website live: <b>https://descaar.github.io</b>. Enable Calendar API, Gmail API, dan Drive API pada Google Cloud project yang sama.</div></article><article class="card"><div class="card-head"><h2>Data & Privacy</h2></div><div class="callout">Versi ini local-first. Histori produktivitas disimpan di browser perangkatmu.</div><div class="simple-list" style="margin-top:12px"><button class="btn btn-secondary" data-act="theme">Toggle dark mode</button><button class="btn btn-secondary" data-act="export">Export JSON</button><button class="btn btn-secondary" data-act="resetData">Reset semua data</button></div></article></div>'}
function render(){nav();side();let pb=$('.profile-chip b');if(pb)pb.textContent=S.profile.name||'Desca';document.documentElement.dataset.theme=S.settings.theme;document.body.classList.toggle('collapsed',!!S.settings.sidebarCollapsed);$('#themeToggle').textContent=S.settings.theme==='dark'?'☀':'☾';({today:todayPage,inbox:inboxPage,tasks:tasksPage,calendar:calendarPage,life:lifePage,google:googlePage,progress:progressPage,goals:goalsPage,study:studyPage,research:()=>domain('research','Research','Catat jam riset dan kemajuan penulisan.'),projects:projectsPage,health:()=>domain('health','Health','Jaga energi dan kebugaran sebagai bagian dari produktivitas.'),finance:financePage,journal:journalPage,analytics:analyticsPage,reviews:reviewPage,achievements:achievementsPage,settings:settingsPage}[route]||todayPage)();updateFocusOverlay()}
function open(html){$('#modal').innerHTML=html;$('#modalBackdrop').hidden=false;document.body.classList.add('modal-open');requestAnimationFrame(()=>$('#modal input:not([disabled]),#modal textarea,#modal select')?.focus())}
function close(){$('#modalBackdrop').hidden=true;$('#modal').innerHTML='';document.body.classList.remove('modal-open')}
function searchItems(q=''){const s=q.trim().toLowerCase();if(!s)return[];let out=[];for(const t of S.tasks)if((t.title||'').toLowerCase().includes(s))out.push({type:'Task',title:t.title,meta:(t.date||'Inbox')+' • '+cat(t.category),route:'tasks'});for(const r of S.routines)if((r.title||'').toLowerCase().includes(s))out.push({type:'Routine',title:r.title,meta:(r.time||'Fleksibel')+' • '+cat(r.category),route:'life'});for(const a of S.activities)if((a.title||'').toLowerCase().includes(s))out.push({type:'Activity',title:a.title,meta:a.date+' • '+cat(a.category)+' • '+mins(a.duration),route:a.category==='study'?'study':a.category==='research'?'research':a.category==='health'?'health':'progress'});for(const g of S.goals)if((g.title||'').toLowerCase().includes(s))out.push({type:'Goal',title:g.title,meta:(g.area||'Goal')+' • '+(g.progress||0)+'%',route:'goals'});for(const n of S.notes)if((n.text||'').toLowerCase().includes(s))out.push({type:'Note',title:n.text.slice(0,90),meta:n.date,route:'inbox'});for(const [d,j] of Object.entries(S.journal))if(Object.values(j||{}).join(' ').toLowerCase().includes(s))out.push({type:'Journal',title:(j.l||j.a||j.t||'Journal entry').slice(0,90),meta:d,route:'journal'});return out.slice(0,18)}
function searchResults(q){const a=searchItems(q);return a.length?a.map(x=>'<button class="search-result" data-act="searchGo" data-route-target="'+x.route+'"><span class="search-type">'+x.type+'</span><span class="search-result-copy"><b>'+esc(x.title)+'</b><small>'+esc(x.meta)+'</small></span><span class="search-arrow">→</span></button>').join(''):'<div class="empty empty-compact"><span class="empty-icon">⌕</span><b>Tidak ada hasil</b><small>Coba kata kunci lain.</small></div>'}
function openSearch(){open('<div class="modal-head"><div><div class="eyebrow">Global Search</div><h2 id="modalTitle">Cari di Desca OS</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="search-modal-box"><span>⌕</span><input id="globalSearchInput" autocomplete="off" placeholder="Cari task, activity, goal, note, journal..."><kbd>Esc</kbd></div><div id="searchResults" class="search-results"><div class="search-hint">Mulai mengetik untuk mencari seluruh workspace.</div></div>')}
function goalForm(g={}){const ms=(g.milestones||[]).join('\n');return'<form id="goalForm"><div class="form-grid"><div class="field full"><label>Nama goal</label><input name="title" required value="'+esc(g.title||'')+'" placeholder="Contoh: Selesaikan skripsi"></div><div class="field"><label>Area</label><input name="area" value="'+esc(g.area||'Academic')+'" placeholder="Academic"></div><div class="field"><label>Deadline</label><input name="deadline" type="date" value="'+(g.deadline||add(today(),30))+'"></div><div class="field"><label>Progress (%)</label><input name="progress" type="number" min="0" max="100" value="'+clamp(+g.progress||0,0,100)+'"></div><div class="field"><label>Status</label><select name="status">'+['active','paused','completed'].map(s=>'<option value="'+s+'" '+(g.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></div><div class="field full"><label>Milestones — satu baris satu milestone</label><textarea name="milestones" rows="6" placeholder="Literature review\nMain theorem\nFinal revision">'+esc(ms)+'</textarea></div></div><input type="hidden" name="id" value="'+(g.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Goal</button></form>'}
function openGoal(g=null){open('<div class="modal-head"><div><div class="eyebrow">Goal</div><h2 id="modalTitle">'+(g?'Edit Goal':'Goal Baru')+'</h2></div><button class="icon-btn" data-act="close">×</button></div>'+goalForm(g||{}))}
function financeForm(){return'<form id="financeForm"><div class="form-grid"><div class="field full"><label>Transaksi</label><input name="title" required placeholder="Contoh: Honor tutor"></div><div class="field"><label>Tipe</label><select name="type"><option value="income">Pemasukan</option><option value="expense">Pengeluaran</option></select></div><div class="field"><label>Nominal</label><input name="amount" type="number" min="0" step="1000" required></div><div class="field"><label>Kategori</label><input name="category" value="General"></div><div class="field"><label>Tanggal</label><input name="date" type="date" value="'+today()+'"></div></div><button class="btn btn-primary" style="margin-top:14px">Simpan Transaksi</button></form>'}
function openFinance(){open('<div class="modal-head"><div><div class="eyebrow">Finance</div><h2 id="modalTitle">Transaksi Baru</h2></div><button class="icon-btn" data-act="close">×</button></div>'+financeForm())}
function starterCard(){if(S.tasks.length||S.activities.length||S.goals.length||S.attendance.length)return'';return'<article class="starter-card"><div><span class="starter-kicker">START HERE</span><h2>Bangun ritme pertamamu.</h2><p>Presensi, buat satu task, lalu mulai Pomodoro. Setelah beberapa sesi, Desca OS mulai membaca pola belajar dan memberi insight otomatis.</p></div><div class="starter-actions"><button class="btn btn-primary" data-act="checkIn">Presensi</button><button class="btn btn-secondary" data-act="addTask">+ Task</button><button class="btn btn-secondary" data-act="focus">Mulai Pomodoro</button></div></article>'}
function taskForm(x={}){return'<form id="taskForm"><div class="form-grid"><div class="field full"><label>Task</label><input name="title" required value="'+esc(x.title||'')+'"></div><div class="field"><label>Tanggal</label><input name="date" type="date" value="'+(x.date||today())+'"></div><div class="field"><label>Estimasi menit</label><input name="estimate" type="number" min="1" value="'+(x.estimate||60)+'"></div><div class="field"><label>Kategori</label><select name="category">'+Object.keys(C).map(c=>'<option value="'+c+'" '+(x.category===c?'selected':'')+'>'+cat(c)+'</option>').join('')+'</select></div><div class="field"><label>Prioritas</label><select name="priority">'+['high','medium','low'].map(p=>'<option '+(x.priority===p?'selected':'')+'>'+p+'</option>').join('')+'</select></div><div class="field full"><label>Goal</label><select name="goalId"><option value="">Tanpa goal</option>'+S.goals.map(g=>'<option value="'+g.id+'" '+(x.goalId===g.id?'selected':'')+'>'+esc(g.title)+'</option>').join('')+'</select></div><div class="field"><label>Inbox</label><select name="inbox"><option value="false">Tidak</option><option value="true" '+(x.inbox?'selected':'')+'>Ya</option></select></div><div class="field"><label>XP otomatis</label><input disabled value="Dihitung saat task selesai"></div></div><input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary" style="margin-top:12px">Simpan</button></form>'}
function activityForm(c='study'){return'<form id="activityForm"><div class="form-grid"><div class="field full"><label>Kegiatan</label><input name="title" required placeholder="Apa yang kamu lakukan?"></div><div class="field"><label>Tanggal</label><input name="date" type="date" value="'+today()+'"></div><div class="field"><label>Jam mulai</label><input name="startTime" type="time" value="'+localTime()+'"></div><div class="field"><label>Durasi (menit)</label><input name="duration" type="number" min="1" value="60"></div><div class="field"><label>Kategori</label><select name="category">'+Object.keys(C).map(x=>'<option value="'+x+'" '+(c===x?'selected':'')+'>'+cat(x)+'</option>').join('')+'</select></div><div class="field"><label>Sifat kegiatan</label><select name="obligation"><option value="mandatory">Wajib</option><option value="important" selected>Penting</option><option value="optional">Opsional</option></select></div><div class="field"><label>Pola</label><select name="rhythm"><option value="nonroutine" selected>Non-rutin / one-off</option><option value="routine">Rutin (manual)</option></select></div><div class="field"><label>Perencanaan</label><select name="planned"><option value="true">Direncanakan</option><option value="false">Spontan / tidak direncanakan</option></select></div><div class="field full"><label>Goal</label><select name="goalId"><option value="">Tanpa goal</option>'+S.goals.map(g=>'<option value="'+g.id+'">'+esc(g.title)+'</option>').join('')+'</select></div><div class="field full"><label>Catatan</label><textarea name="notes" rows="3" placeholder="Opsional: lokasi, konteks, hasil, atau hal penting lainnya."></textarea></div><div class="field full"><label>XP</label><input disabled value="Otomatis dari durasi, kategori, sifat kegiatan, dan sumber"></div></div><button class="btn btn-primary" style="margin-top:12px">Catat Kegiatan</button></form>'}
function routineForm(r={}){const days=(r.days||[1,2,3,4,5]).map(Number);return'<form id="routineForm"><div class="form-grid"><div class="field full"><label>Nama kegiatan rutin</label><input name="title" required value="'+esc(r.title||'')+'" placeholder="Contoh: Kuliah, olahraga, belajar malam"></div><div class="field"><label>Jam</label><input name="time" type="time" value="'+esc(r.time||'07:00')+'"></div><div class="field"><label>Durasi (menit)</label><input name="duration" type="number" min="1" value="'+(r.duration||60)+'"></div><div class="field"><label>Kategori</label><select name="category">'+Object.keys(C).map(x=>'<option value="'+x+'" '+((r.category||'personal')===x?'selected':'')+'>'+cat(x)+'</option>').join('')+'</select></div><div class="field"><label>Sifat</label><select name="obligation"><option value="mandatory" '+(r.obligation==='mandatory'?'selected':'')+'>Wajib</option><option value="important" '+((r.obligation||'important')==='important'?'selected':'')+'>Penting</option><option value="optional" '+(r.obligation==='optional'?'selected':'')+'>Opsional</option></select></div><div class="field full"><label>Hari aktif</label><div class="day-picker">'+DAY_NAMES.map((n,i)=>'<label class="day-check"><input type="checkbox" name="days" value="'+i+'" '+(days.includes(i)?'checked':'')+'><span>'+n+'</span></label>').join('')+'</div></div><div class="field full"><label>Linked Goal</label><select name="goalId"><option value="">Tanpa goal</option>'+S.goals.map(g=>'<option value="'+g.id+'" '+(r.goalId===g.id?'selected':'')+'>'+esc(g.title)+'</option>').join('')+'</select></div></div><input type="hidden" name="id" value="'+(r.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Routine</button></form>'}
function openRoutine(r=null){open('<div class="modal-head"><div><div class="eyebrow">LIFE LOG</div><h2 id="modalTitle">'+(r?'Edit Routine':'Routine Baru')+'</h2></div><button class="icon-btn" data-act="close">×</button></div>'+routineForm(r||{}))}
function quick(type='task',c='study'){open('<div class="modal-head"><h2>Quick Add</h2><button class="icon-btn" data-act="close">×</button></div><div class="tabs"><button class="tab '+(type==='task'?'active':'')+'" data-act="qtab" data-tab="task">Task</button><button class="tab '+(type==='activity'?'active':'')+'" data-act="qtab" data-tab="activity">Activity</button><button class="tab '+(type==='routine'?'active':'')+'" data-act="qtab" data-tab="routine">Routine</button></div><div id="qform">'+(type==='task'?taskForm():type==='routine'?routineForm():activityForm(c))+'</div>')}
function toggle(id){let x=S.tasks.find(t=>t.id===id);if(!x)return;x.status=x.status==='done'?'todo':'done';save();toast(x.status==='done'?'Task selesai · +'+taskXP(x)+' XP otomatis':'Task dibuka kembali · XP disesuaikan otomatis');render()}
function setPomodoroPreset(p){if(focus.running)return;S.settings.pomodoroPreset=p;if(p==='classic'){S.settings.pomodoroFocus=25;S.settings.pomodoroShortBreak=5;S.settings.pomodoroLongBreak=15}else if(p==='deep'){S.settings.pomodoroFocus=50;S.settings.pomodoroShortBreak=10;S.settings.pomodoroLongBreak=20}syncPomodoro();focus.phase='focus';focus.cycle=1;focus.startedAt=null;focus.total=phaseMinutes()*60;focus.left=focus.total;save();render()}
function setFocusPhase(p){focus.phase=p;focus.running=false;clearInterval(focus.timer);focus.timer=null;focus.endsAt=null;focus.startedAt=null;focus.total=phaseMinutes()*60;focus.left=focus.total}
function tickFocus(){if(!focus.running)return;focus.left=Math.max(0,Math.ceil((focus.endsAt-Date.now())/1000));let e=$('#focusClock');if(e)e.textContent=focusTimeText();updateFocusOverlay();if(focus.left<=0)completePomodoroPhase()}
function completePomodoroPhase(){clearInterval(focus.timer);focus.timer=null;focus.running=false;const cycles=clamp(+S.settings.pomodoroCycles||4,1,12);if(focus.phase==='focus'){const d=Math.round(focus.total/60),a={id:uid('a'),date:dateFromTs(focus.startedAt||Date.now()),startTime:timeFromTs(focus.startedAt||Date.now()),title:focus.label||'Pomodoro Focus',category:focus.category||'study',duration:d,source:'pomodoro',completed:true,pomodoroCycle:focus.cycle,goalId:null,rhythm:'nonroutine',obligation:'important',planned:true,notes:''};S.activities.push(a);const earned=activityXP(a),long=focus.cycle>=cycles;setFocusPhase(long?'longBreak':'shortBreak');save();toast('Pomodoro selesai · +'+earned+' XP otomatis');render();updateFocusOverlay()}else{const wasLong=focus.phase==='longBreak';if(wasLong)focus.cycle=1;else focus.cycle=Math.min(cycles,focus.cycle+1);setFocusPhase('focus');toast('Break selesai · siap fokus lagi');render();updateFocusOverlay()}}
function focusToggle(){if(focus.running){focus.left=Math.max(1,Math.ceil((focus.endsAt-Date.now())/1000));focus.running=false;clearInterval(focus.timer);focus.timer=null;render();return}if(focus.phase==='focus'){focus.label=$('#focusLabel')?.value.trim()||focus.label||'Belajar Fokus';focus.category=$('#focusCategory')?.value||focus.category||'study';if(!focus.startedAt)focus.startedAt=Date.now()}focus.running=true;focus.endsAt=Date.now()+focus.left*1000;clearInterval(focus.timer);focus.timer=setInterval(tickFocus,250);enterFocusMode(true);render()}
function resetFocus(){if(focus.startedAt&&focus.phase==='focus'&&focus.left<focus.total&&!confirm('Akhiri sesi fokus ini? Waktu yang belum selesai tidak akan mendapat bonus Pomodoro.'))return;clearInterval(focus.timer);focus.timer=null;focus.running=false;focus.endsAt=null;focus.startedAt=null;focus.zen=false;focus.total=phaseMinutes()*60;focus.left=focus.total;exitNativeFullscreen();render()}
function skipBreak(){if(focus.phase==='focus')return;const cycles=clamp(+S.settings.pomodoroCycles||4,1,12),wasLong=focus.phase==='longBreak';if(wasLong)focus.cycle=1;else focus.cycle=Math.min(cycles,focus.cycle+1);setFocusPhase('focus');render();updateFocusOverlay()}
document.addEventListener('click',e=>{let r=e.target.closest('[data-route]')?.dataset.route;if(r){route=r;location.hash=r;$('#sidebar').classList.remove('open');close();render();return}let x=e.target.closest('[data-act]');if(!x)return;let a=x.dataset.act,id=x.dataset.id;if(a==='close')close();if(a==='toggle')toggle(id);if(a==='addTask')quick('task');if(a==='addActivity')quick('activity',x.dataset.cat||'study');if(a==='newRoutine')openRoutine();if(a==='editRoutine'){let r=S.routines.find(v=>v.id===id);if(r)openRoutine(r)}if(a==='toggleRoutine'){let r=S.routines.find(v=>v.id===id);if(r){r.active=r.active===false?true:false;save();render()}}if(a==='completeRoutine')completeRoutine(id);if(a==='skipRoutine')skipRoutine(id);if(a==='qtab'){$('#qform').innerHTML=x.dataset.tab==='task'?taskForm():x.dataset.tab==='routine'?routineForm():activityForm();$('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===x.dataset.tab))}if(a==='editTask'){let t=S.tasks.find(v=>v.id===id);quick('task');$('#qform').innerHTML=taskForm(t)}if(a==='newGoal')openGoal();if(a==='editGoal'){let g=S.goals.find(v=>v.id===id);if(g)openGoal(g)}if(a==='newFinance')openFinance();if(a==='searchGo'){route=x.dataset.routeTarget||'today';location.hash=route;close();render()}if(a==='focus')focusToggle();if(a==='resetFocus')resetFocus();if(a==='skipBreak')skipBreak();if(a==='minimizeFocus')minimizeFocus();if(a==='restoreFocus')enterFocusMode(true);if(a==='pomoPreset')setPomodoroPreset(x.dataset.preset);if(a==='checkIn')checkIn();if(a==='connectGoogle')connectGoogle();if(a==='disconnectGoogle')disconnectGoogle();if(a==='syncGoogle')syncGoogle();if(a==='calendarToActivity'){let ev=G.calendar.find(v=>v.id===x.dataset.eventId);if(ev){let start=gEventStart(ev),date=start?start.slice(0,10):today(),st=start&&start.includes('T')?start.slice(11,16):localTime();quick('activity','personal');requestAnimationFrame(()=>{let f=$('#activityForm');if(f){f.elements.title.value=ev.summary||'Calendar event';f.elements.date.value=date;f.elements.startTime.value=st;f.elements.planned.value='true'}})}}if(a==='calendarToTask'){let ev=G.calendar[+x.dataset.idx];if(ev){let start=gEventStart(ev),date=start?start.slice(0,10):today();S.tasks.push({id:uid('t'),title:ev.summary||'Calendar event',date,status:'todo',priority:'medium',category:'personal',goalId:null,estimate:60,inbox:false});save();toast('Calendar event ditambahkan ke Tasks');render()}}if(a==='saveNote'){let q=$('#quickNote')?.value.trim();if(q){S.notes.push({id:uid('n'),date:today(),text:q});save();toast('Catatan tersimpan');$('#quickNote').value=''}}if(a==='saveJournal'){S.journal[today()]={a:$('#ja').value,l:$('#jl').value,i:$('#ji').value,t:$('#jt').value};save();toast('Refleksi tersimpan');render()}if(a==='theme'){S.settings.theme=S.settings.theme==='dark'?'light':'dark';save();render()}if(a==='saveSettings'){S.profile.name=$('#sn').value||'Desca';S.profile.dailyFocusTarget=Math.max(1,+$('#sd').value||240);S.profile.weeklyTarget=Math.max(1,+$('#sw').value||1800);const pf=$('#spf'),ps=$('#sps'),pl=$('#spl'),pc=$('#spc'),gc=$('#sgcid');if(gc)S.settings.googleClientId=gc.value.trim();if(pf){S.settings.pomodoroFocus=clamp(+pf.value||25,5,180);S.settings.pomodoroShortBreak=clamp(+ps.value||5,1,60);S.settings.pomodoroLongBreak=clamp(+pl.value||15,1,90);S.settings.pomodoroCycles=clamp(+pc.value||4,1,12);S.settings.pomodoroPreset='custom';syncPomodoro()}save();toast('Settings tersimpan');render()}if(a==='export'){let b=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),l=document.createElement('a');l.href=u;l.download='desca-os-'+today()+'.json';l.click();URL.revokeObjectURL(u)}if(a==='resetData'){if(confirm('Hapus seluruh data Desca OS di browser ini?')){S=seed();syncPomodoro();save();render()}}});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,fd=new FormData(f),d=Object.fromEntries(fd);if(f.id==='taskForm'){let old=S.tasks.find(x=>x.id===d.id),o={id:d.id||uid('t'),title:d.title,date:d.inbox==='true'?null:d.date,status:old?.status||'todo',priority:d.priority,category:d.category,goalId:d.goalId||null,estimate:+d.estimate||0,inbox:d.inbox==='true'};old?Object.assign(old,o):S.tasks.push(o);save();close();toast('Task tersimpan');render()}if(f.id==='activityForm'){const a={id:uid('a'),date:d.date,title:d.title,category:d.category,duration:Math.max(1,+d.duration||1),startTime:d.startTime||localTime(),goalId:d.goalId||null,source:'manual',completed:true,rhythm:d.rhythm||'nonroutine',obligation:d.obligation||'important',planned:d.planned!=='false',notes:(d.notes||'').trim()};S.activities.push(a);save();close();toast('Kegiatan tercatat · +'+activityXP(a)+' XP otomatis');render()}if(f.id==='routineForm'){const days=fd.getAll('days').map(Number);if(!days.length){toast('Pilih minimal satu hari');return}let old=S.routines.find(x=>x.id===d.id),r={id:d.id||uid('r'),title:d.title.trim(),time:d.time||'',duration:Math.max(1,+d.duration||30),category:d.category||'personal',obligation:d.obligation||'important',days,goalId:d.goalId||null,active:old?.active!==false};old?Object.assign(old,r):S.routines.push(r);save();close();toast(old?'Routine diperbarui':'Routine dibuat');render()}if(f.id==='goalForm'){let old=S.goals.find(x=>x.id===d.id),g={id:d.id||uid('g'),title:d.title.trim(),area:(d.area||'Goal').trim(),deadline:d.deadline||add(today(),30),progress:clamp(+d.progress||0,0,100),status:d.status||'active',milestones:(d.milestones||'').split(/\n+/).map(x=>x.trim()).filter(Boolean)};old?Object.assign(old,g):S.goals.push(g);save();close();toast(old?'Goal diperbarui':'Goal dibuat');render()}if(f.id==='financeForm'){S.finance.push({id:uid('f'),title:d.title.trim(),type:d.type==='expense'?'expense':'income',amount:Math.max(0,+d.amount||0),category:(d.category||'General').trim(),date:d.date||today()});save();close();toast('Transaksi tersimpan');render()}});
$('#quickAdd').onclick=()=>quick('task');$('#searchOpen').onclick=()=>openSearch();$('#themeToggle').onclick=()=>{S.settings.theme=S.settings.theme==='dark'?'light':'dark';save();render()};$('#sidebarToggle').onclick=()=>{S.settings.sidebarCollapsed=!S.settings.sidebarCollapsed;save();render()};$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')close()};document.addEventListener('input',e=>{if(e.target.id==='globalSearchInput'){let box=$('#searchResults');if(box)box.innerHTML=e.target.value.trim()?searchResults(e.target.value):'<div class="search-hint">Mulai mengetik untuk mencari seluruh workspace.</div>'}});document.addEventListener('keydown',e=>{const edit=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'');if(focus.zen&&e.code==='Space'&&!edit){e.preventDefault();focusToggle();return}if(focus.zen&&e.key==='Escape'){e.preventDefault();minimizeFocus();return}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'&&!$('#modalBackdrop').hidden)close()});window.onhashchange=()=>{let r=location.hash.slice(1);if(R[r]){route=r;render()}};if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});render();
